// project set up
tiles.setCurrentTilemap(tilemap`myTilemap`)

// sprite set up
let mySprite = sprites.create(assets.image`myImage`, SpriteKind.Player)
tiles.placeOnTile(mySprite, tiles.getTileLocation(1, 1))
mySprite.setScale(0.9, ScaleAnchor.Middle)
controller.moveSprite(mySprite)
scene.cameraFollowSprite(mySprite)

// exit tile set up
let wallTileList = tiles.getTilesByType(assets.tile`wallTile`)
let randomWallTile = wallTileList[randint(0, wallTileList.length - 1)]
tiles.setTileAt(tiles.getTileLocation(0, 0), assets.tile`exitTile`)
tiles.setWallAt(tiles.getTileLocation(randomWallTile.column, randomWallTile.row), false)

// box tile set up
game.onUpdateInterval(200, function () {
    let floorTileList = tiles.getTilesByType(assets.tile`floorTile`)
    let getRandomFloor = floorTileList[randint(0, floorTileList.length - 1)]
    tiles.setTileAt(tiles.getTileLocation(getRandomFloor.column, getRandomFloor.row), assets.tile`boxTile`)
    if (tiles.getTilesByType(img` `) == 0) {
        game.gameOver(false)
    }
})

